mapper.select:
select
con.Con_Name as conName, c1.C_Name as meaSupeName, c1.C_Abbreviation as meaSupeAbbName, c2.C_Name as meaContName, c2.C_Abbreviation as meaContAbbName, ces.Ec_Construction_Name as ecConstructionName, ces.ec_Apply_Money as ecApplyMoney, ces.ec_Change_Type as ecChangeType, mn.* from Con_Measure mn left join Con_Contract con on con.Con_Id = mn.Con_Id
left join SYS_Company c1 on c1.C_Id = mn.Mea_Supervisor_Id left join SYS_Company c2 on c2.C_Id = mn.Mea_Contractor_Id left join con_ec ces on ces.ec_Id=mn.con_Ec_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time DESC
